TPickANumber::TPickANumber(int lowBound, int high)
    : m_low(lowBound),
      m_numbersLeft(high - lowBound + 1),
      m_available(m_numbersLeft, 1)
{
}

// E:\gamedcs\misc.cpp:849. Original: TPickANumber::Pick.
